const j = $input.first().json;
let query, categories, excludeUserId, limit;
if (j.query !== undefined) {
  query = typeof j.query === 'string' && j.query.trim() ? j.query.trim() : null;
  const rawLimit = j.limit;
  limit = (rawLimit !== null && rawLimit !== undefined && Number.isFinite(Number(rawLimit)) && Number(rawLimit) > 0)
    ? Math.max(1, Math.min(20, Number(rawLimit))) : 8;
  categories = typeof j.categories === 'string' && j.categories.trim()
    ? j.categories.trim().split(',').map(c => c.trim().toLowerCase()).filter(Boolean) : null;
  excludeUserId = typeof j.excludeUserId === 'string' && j.excludeUserId.trim() ? j.excludeUserId.trim() : null;
} else {
  const raw = j.input;
  const inp = typeof raw === 'string' ? JSON.parse(raw) : (raw || j);
  query = typeof inp?.query === 'string' && inp.query.trim() ? inp.query.trim() : null;
  const rawLimit = inp?.limit;
  limit = (rawLimit !== null && rawLimit !== undefined && Number.isFinite(Number(rawLimit)) && Number(rawLimit) > 0)
    ? Math.max(1, Math.min(20, Number(rawLimit))) : 8;
  categories = Array.isArray(inp?.categories) && inp.categories.length > 0
    ? inp.categories.filter(c => typeof c === 'string' && c.trim()).map(c => c.trim().toLowerCase()) : null;
  if (categories && categories.length === 0) categories = null;
  excludeUserId = typeof inp?.excludeUserId === 'string' && inp.excludeUserId.trim() ? inp.excludeUserId.trim() : null;
}
if (query === null && categories === null) {
  return [{ json: { books: [], count: 0, ids_for_bookIds: [], error: 'Debes proporcionar al menos una query.' } }];
}
return [{ json: { query, categories, excludeUserId, limit } }];

// Normaliza y devuelve los libros encontrados como array JSON
const rows = $input.all();
const books = [];
const seen = new Set();

for (const row of rows) {
  const j = row.json;
  if (!j || j.error) continue;
  const id = Number(j.id);
  if (!Number.isFinite(id) || id <= 0 || seen.has(id)) continue;
  seen.add(id);
  books.push({
    id,
    title: j.title || '',
    author: j.author || '',
    description: j.description || null,
    coverUrl: j.coverUrl || null,
    categories: Array.isArray(j.categories) ? j.categories.filter(Boolean) : []
  });
}

const ids_for_bookIds = books.map(b => b.id);
return [{ json: { books, count: books.length, ids_for_bookIds } }];
